import { createAgUiEncoderState, stampAgUiEventTiming } from "./encoder.js";
const encoder = new TextEncoder();
function formatAgUiSseEventWithId(event, eventId) {
    const idLine = eventId === null ? "" : `id: ${eventId}\n`;
    return encoder.encode(`${idLine}event: ${event.event}\ndata: ${JSON.stringify(event.payload)}\n\n`);
}
function invokeFailWithoutLeaking(fail, error) {
    return fail(error).catch(() => undefined);
}
function isRecord(value) {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}
function normalizeSnapshot(snapshot) {
    return isRecord(snapshot) ? snapshot : {};
}
/** Create AG-UI response stream. */
export function createAgUiResponseStream(input) {
    let streamClosed = false;
    let nextEventId = 1;
    return new ReadableStream({
        start(controller) {
            const timingState = input.encoder.timingState ?? createAgUiEncoderState();
            const writeEvent = (event) => {
                if (streamClosed) {
                    return false;
                }
                try {
                    const [timed] = stampAgUiEventTiming(timingState, [event]);
                    controller.enqueue(formatAgUiSseEventWithId(timed ?? event, nextEventId));
                    nextEventId += 1;
                    return true;
                }
                catch {
                    streamClosed = true;
                    return false;
                }
            };
            const closeStream = () => {
                if (streamClosed) {
                    return;
                }
                if (controller.desiredSize === null) {
                    streamClosed = true;
                    return;
                }
                controller.close();
                streamClosed = true;
            };
            void (async () => {
                const state = input.initialState;
                try {
                    if (!writeEvent({
                        event: "RunStarted",
                        payload: {
                            runId: input.agUiInput.runId,
                            threadId: input.agUiInput.threadId,
                            agentId: input.agentId,
                        },
                    })) {
                        return;
                    }
                    if (!writeEvent({
                        event: "StateSnapshot",
                        payload: {
                            snapshot: normalizeSnapshot(input.agUiInput.state),
                        },
                    })) {
                        return;
                    }
                    if (!writeEvent({
                        event: "MessagesSnapshot",
                        payload: {
                            messages: input.agUiInput.messages,
                        },
                    })) {
                        return;
                    }
                    for await (const chunk of input.execution.agentUIStream) {
                        if (streamClosed) {
                            return;
                        }
                        input.onChunk?.(state, chunk);
                        for (const event of input.encoder.encode(chunk)) {
                            if (!writeEvent(event)) {
                                return;
                            }
                        }
                    }
                    if (streamClosed) {
                        return;
                    }
                    await input.execution.waitForFinish();
                    if (streamClosed) {
                        return;
                    }
                    for (const event of input.encoder.finalize(input.getFinalResponse?.(state) ?? null)) {
                        if (!writeEvent(event)) {
                            return;
                        }
                    }
                }
                catch (error) {
                    await invokeFailWithoutLeaking(input.execution.fail, error);
                    writeEvent({
                        event: "RunError",
                        payload: {
                            code: "STREAM_ERROR",
                            message: error instanceof Error ? error.message : String(error),
                        },
                    });
                }
                finally {
                    closeStream();
                }
            })();
        },
        cancel() {
            streamClosed = true;
        },
    });
}
